use serde_json::Value;

pub fn solve(input: Value) -> Value {
    let year = input.as_i64().unwrap();
    let month = input.as_i64().unwrap();
    let day = input.as_i64().unwrap();

    if year < 1 || year > 9999 || month < 1 || month > 12 || day < 1 || day > 31 {
        return Value::Bool(false);
    }

    if month == 2 {
        if day > 29 && (year % 4 == 0 && year % 100 != 0) || (year % 400 == 0) {
            return Value::Bool(false);
        }
    }

    Value::Bool(true)
}
